from decimal import Decimal

import pytest

from refproj.pricing import add_tax


def test_tax_is_added_and_rounded_to_cents() -> None:
    assert add_tax(Decimal("19.99"), Decimal("7.5")) == Decimal("21.49")


def test_tax_tie_goes_to_the_even_cent() -> None:
    assert add_tax(Decimal("0.50"), Decimal("5")) == Decimal("0.52")
    assert add_tax(Decimal("0.50"), Decimal("15")) == Decimal("0.58")


def test_tax_rate_of_zero_returns_the_price_in_cents() -> None:
    assert str(add_tax(Decimal("10"), Decimal("0"))) == "10.00"


def test_negative_tax_rate_is_rejected() -> None:
    with pytest.raises(ValueError, match="tax rate"):
        add_tax(Decimal("10.00"), Decimal("-1"))

