from decimal import Decimal

import pytest

from refproj.pricing import average


def test_average_is_the_arithmetic_mean() -> None:
    assert average([Decimal("1.00"), Decimal("2.00"), Decimal("6.00")]) == Decimal("3.00")


def test_average_rounds_half_up_to_cents() -> None:
    result = average([Decimal("0.02"), Decimal("0.03")])
    assert result == Decimal("0.03")
    assert result.as_tuple().exponent == -2


def test_average_accepts_a_generator() -> None:
    assert average(Decimal(n) for n in (1, 2, 3)) == Decimal("2.00")


def test_average_counts_zero_prices() -> None:
    assert average([Decimal("0.00"), Decimal("4.00")]) == Decimal("2.00")


def test_average_of_no_prices_is_rejected() -> None:
    with pytest.raises(ValueError, match="no prices"):
        average([])

